	x = [0] * (n + 1)
	y = [0] * (n + 1)
	p = [0] * (n + 1)
	for i in range(1, n + 1):
		(x[i], y[i], p[i]) = map(int, stdin.readline().split())
	G = DinicsAlgo(n + 2)
	V = 0
	for i in range(1, n + 1):
		V += abs(arr[x[i]][y[i]] * p[i])
		if arr[x[i]][y[i]] >= 0:
			G.add_edge(0, i, arr[x[i]][y[i]] * p[i])
		if arr[x[i]][y[i]] < 0:
